class Solution:
    def removeInvalidParentheses(self, s: str) -> List[str]:
        # Calculate the minimum left and right parantheses to remove
        def findMinRemove(s):
            left_removed, right_removed = 0, 0
            for c in s:
                if c == '(':
                    left_removed += 1
                elif c == ')':
                    if not left_removed:
                        right_removed += 1
                    else:
                        left_removed -= 1
            return (left_removed, right_removed)

        # Check whether s is valid or not.
        def isValid(s):
            sum = 0
            for c in s:
                if c == '(':
                    sum += 1
                elif c == ')':
                    sum -= 1
                if sum < 0:
                    return False
            return sum == 0

        def removeInvalidParenthesesHelper(start, left_removed, right_removed):
            if left_removed == 0 and right_removed == 0:
                tmp = ""
                for i, c in enumerate(s):
                    if i not in removed:
                        tmp += c
                if isValid(tmp):
                    res.append(tmp)
                return

            for i in range(start, len(s)):
                if right_removed == 0 and left_removed > 0 and s[i] == '(':
                    if i == start or s[i] != s[i - 1]:  # Skip duplicated.
                        removed[i] = True
                        removeInvalidParenthesesHelper(i + 1, left_removed - 1, right_removed)
                        del removed[i]
                elif right_removed > 0 and s[i] == ')':
                    if i == start or s[i] != s[i - 1]:  # Skip duplicated.
                        removed[i] = True
                        removeInvalidParenthesesHelper(i + 1, left_removed, right_removed - 1)
                        del removed[i]

        res, removed = [], {}
        (left_removed, right_removed) = findMinRemove(s)
        removeInvalidParenthesesHelper(0, left_removed, right_removed)
        return res

from typing import List
class Solution:
    def maxProfit(self, prices: List[int]) -> int:


        cache = {}
        def dfs(i, buying):

            if i >= len(prices):
                return 0

            if (i, buying) in cache:
                return cache[(i, buying)]

            if buying:
                # if have sell the share in previous step
                # then currently we have two options
                # either buy or not buy(cooldown)

                # we have bought so, increment the index and set buying flag to not buying
                # and don't forget that we bought so, we have to reduce that share amount from profit
                buy = dfs(i+1, not buying) - prices[i] 

                cooldown = dfs(i+1, buying)

                profit = max( buy, cooldown )
                cache[(i, buying)] = profit

            else:
                # we have sell the share so, 
                # we cannot buy next share we have to skip the next price(cooldown for one day)
                # set (not buying) flag to buying
                # we also have to add that share price to profit
                sell = dfs(i+2, not buying) + prices[i] 

                cooldown = dfs(i+1, buying)

                profit = max( sell, cooldown )
                cache[(i, buying)] = profit

            return cache[(i,  buying)]

        return dfs(0, True)
